// 거래소별 가상 잔액 계산 — 페이퍼 트레이딩 봇의 «진입 잔액 관문», «청산 알림», «07:40 상태 보고»가
// 모두 이 워크플로 하나를 부른다 (2026-09-29). 계산을 한 곳에 두어 세 숫자가 어긋나지 않게 한다.
//
// 원장은 대시보드 «거래소별 잔액»(ledger/ledger.js)과 같은 방식이다:
//   시드 $10,000을 가동일에 코빗(원화)·OKX(USDT)에 반씩 넣고, 청산 거래를 두 다리로 쌓고,
//   ledger/config.json 의 리밸런싱(가상 이체)을 반영한다. 설정과 옛 거래 환율 백필은
//   대시보드(Vercel)에서 받아 와서 두 곳이 같은 파일을 쓴다.
//   코빗 여유 = 원화 예수금 (보유 코인 매수대금은 이미 빠져 있다)
//   OKX 여유 = 평가금액(예수금 + 미실현손익) − 보유 포지션 증거금(1배 = 진입 명목)
//   보유 포지션은 코빗 최우선 매수호가·OKX 최종가로 평가한다.
// 한 자리에 코빗은 $1,000어치 원화, OKX는 $1,000 증거금 + 진입 수수료가 필요하다.
const POSITION_USD = 1000;          // 봇 «가상 진입 기록»의 positionSize와 같아야 한다
const FEE_RATE = 0.0002;            // 해외 지정가 편도
const MAX_POSITIONS = 4;            // 봇 «진입 가능 여부 판단»과 같아야 한다

const num = function (v) { const n = Number(v); return isFinite(n) && n !== 0 ? n : null; };
const r2 = function (v) { return Math.round(v * 100) / 100; };
const usd0 = function (v) { return '$' + Math.round(Math.abs(v)).toLocaleString('en-US'); };

const cfg = $('원장 설정 조회').first().json || {};
const backfill = $('원장 백필 조회').first().json || {};
const fxBody = $('환율 조회').first().json;
const fx = (fxBody && fxBody.rates && fxBody.rates.KRW) ? Number(fxBody.rates.KRW) : null;

if (!num(cfg.seedUsd) || !num(cfg.startFx) || !fx) {
  const reason = !fx ? '환율 없음' : '원장 설정을 받지 못함';
  return [{ json: { checked: false, reason: reason, line: '💰 거래소별 잔액: 계산 실패 (' + reason + ')' } }];
}

// 지금 가격 (보유 포지션 평가용)
const kBid = {};
const kBody = $('코빗 가격 조회').first().json || {};
(kBody.data || []).forEach(function (r) {
  const m = String(r.symbol || '').match(/^(.+)_krw$/);
  if (m) kBid[m[1].toUpperCase()] = num(r.bestBidPrice) || num(r.close);
});
const oLast = {};
const oBody = $('OKX 가격 조회').first().json || {};
(oBody.data || []).forEach(function (r) {
  const m = String(r.instId || '').match(/^(.+)-USDT-SWAP$/);
  if (m) oLast[m[1]] = num(r.last);
});

const trades = $('전체 거래 조회').all().map(function (i) { return i.json; })
  .filter(function (t) { return t && t.coin && t.status !== 'VOID'; });

const half = Number(cfg.seedUsd) / 2;
let korbitKrw = half * Number(cfg.startFx);
let okxCash = half;
let okxUnreal = 0, okxMargin = 0, korbitHoldKrw = 0;
let openCount = 0, closedCount = 0, unpriced = 0;
const missing = [];

(cfg.transfers || []).forEach(function (tr) {
  if (new Date(tr.time).getTime() > Date.now()) return;
  const usd = Number(tr.usd), tfx = Number(tr.fx);
  if (tr.from === 'korbit') { korbitKrw -= usd * tfx; okxCash += usd; }
  else { okxCash -= usd; korbitKrw += usd * tfx; }
});

trades.forEach(function (t) {
  const b = backfill[t.id] || {};
  const pe = Number(t.entryPremium) / 100;
  const entryFp = num(t.entryForeignPrice) || num(b.entryForeignPrice);
  const entryFx = num(t.entryFx) || num(b.entryFx) || (entryFp ? Number(t.entryPrice) / (entryFp * (1 + pe)) : null);
  const q = entryFx ? Number(t.positionSize) * entryFx / Number(t.entryPrice) : null;
  if (!q || !entryFp) { missing.push(t.id); return; }

  if (t.status === 'CLOSED') {
    const exitFx = num(t.exitFx) || num(b.exitFx);
    let exitFp = num(t.exitForeignPrice) || num(b.exitForeignPrice);
    if (!exitFp && exitFx) exitFp = Number(t.exitPrice) / (exitFx * (1 + Number(t.exitPremium) / 100));
    if (!exitFp) { missing.push(t.id); return; }
    korbitKrw += q * (Number(t.exitPrice) - Number(t.entryPrice));
    okxCash += q * (entryFp - exitFp) - Number(t.feeEntry || 0) - Number(t.feeExit || 0);
    closedCount++;
    return;
  }

  // OPEN
  openCount++;
  korbitKrw -= q * Number(t.entryPrice);
  okxCash -= Number(t.feeEntry || 0);
  okxMargin += q * entryFp;
  const bid = kBid[t.coin], fp = oLast[t.coin];
  if (!bid || !fp) unpriced++;
  if (fp) okxUnreal += q * (entryFp - fp);
  korbitHoldKrw += q * (bid || Number(t.entryPrice));
});

const korbitFree = korbitKrw / fx;
const okxFree = okxCash + okxUnreal - okxMargin;
const korbitSlots = Math.max(0, Math.floor(korbitFree / POSITION_USD));
const okxSlots = Math.max(0, Math.floor(okxFree / (POSITION_USD * (1 + FEE_RATE))));

const korbitTotal = (korbitKrw + korbitHoldKrw) / fx;
const okxTotal = okxCash + okxUnreal;
const total = korbitTotal + okxTotal;
const korbitShare = korbitTotal / total * 100;
const okxShare = okxTotal / total * 100;
const rebalanceUsd = korbitTotal - total / 2; // 양수면 코빗→OKX

const line = '💰 코빗 ' + usd0(korbitTotal) + ' (' + korbitShare.toFixed(1) + '%) · OKX ' + usd0(okxTotal) +
  ' (' + okxShare.toFixed(1) + '%) · 합계 ' + usd0(total) + ' · ' +
  (Math.abs(rebalanceUsd) < 1 ? '50:50 균형'
    : '50:50까지 ' + (rebalanceUsd > 0 ? '코빗→OKX ' : 'OKX→코빗 ') + usd0(rebalanceUsd)) +
  (unpriced ? ' (보유 ' + unpriced + '종목 원가 기준)' : '');

return [{ json: {
  checked: true,
  fx: fx,
  korbitTotal: r2(korbitTotal),
  okxTotal: r2(okxTotal),
  total: r2(total),
  korbitShare: Math.round(korbitShare * 10) / 10,
  okxShare: Math.round(okxShare * 10) / 10,
  korbitFree: r2(korbitFree),
  okxFree: r2(okxFree),
  korbitSlots: korbitSlots,
  okxSlots: okxSlots,
  balanceSlots: Math.min(korbitSlots, okxSlots),
  countSlots: Math.max(0, MAX_POSITIONS - openCount),
  openCount: openCount,
  closedCount: closedCount,
  rebalanceUsd: r2(rebalanceUsd),
  missing: missing,
  line: line
} }];

